import React from "react";
import AOS from "aos";
import "aos/dist/aos.css";
import "../components/BestProducts.css";

import img1 from "../assests/ajwa.jpg";
import img2 from "../assests/almonds.jpg";
import img3 from "../assests/pistachios.jpg";
import img4 from "../assests/mixedseeds.jpg";
import img5 from "../assests/organicseeds.jpg";
import img6 from "../assests/blackraisins.jpg";

export default function BestProducts() {
  const products = [
    { name: "Ajwa Dates", price: "₹450", image: img1 },
    { name: "Almonds", price: "₹650", image: img2 },
    { name: "Pistachios", price: "₹750", image: img3 },
    { name: "Mixed Nuts", price: "₹550", image: img4 },
    { name: "Organic Seeds", price: "₹299", image: img5 },
    { name: "Black Raisins", price: "₹190", image: img6 },
  ];

  return (
    <div className="container py-5" id="best-products">
      <h1 className="text-center mb-4 fw-bold">Best Sellers</h1>

      <div className="row g-4">
        {products.map((p, index) => (
          <div
            className="col-6 col-md-4 col-lg-3"
            key={index}
            data-aos="fade-up"
          >
            <div className="card shadow-sm border-0 h-100">
              <img
                src={p.image}
                className="card-img-top img-fluid w-100 object-fit-cover"
                alt={p.name}
                style={{ height: "180px" }}
              />

              <div className="card-body text-center">
                <h5 className="card-title">{p.name}</h5>
                <p className="card-text text-muted">{p.price}</p>

                {/* Weight Dropdown */}
                <select className="form-select form-select-sm mb-3">
                  <option value="">Select Weight</option>
                  <option value="250g">250g</option>
                  <option value="500g">500g</option>
                  <option value="1kg">1kg</option>
                </select>

                {/* Buttons in same line */}
                <div className="d-flex gap-2">
                  <button className="btn btn-outline-dark btn-sm w-50">
                    Add to Cart
                  </button>
                  <button className="btn btn-dark btn-sm w-50">
                    Buy Now
                  </button>
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
